INSERT INTO "conversation_generation_attempt" (
    "creator_id", "modifier_id", "round_id", "attempt_id", "capability_key", "model", "status",
    "provider_request_id", "error_code", "error_message", "start_time", "end_time"
) VALUES (
    #{creatorId}, #{modifierId}, #{roundId}, #{attemptId}, #{capabilityKey}, #{model}, #{status},
    COALESCE(#{providerRequestId}, ''), COALESCE(#{errorCode}, ''), COALESCE(#{errorMessage}, ''),
    #{startTime}, #{endTime}
)
ON CONFLICT ("attempt_id") DO UPDATE SET "attempt_id" = EXCLUDED."attempt_id"
